INSERT INTO product (sku, name, description, price, stock, light, watering, pet_safe, image_path, category_id) VALUES
  ('FOL-MONSTERA', 'Monstera Deliciosa', 'Iconic split-leaf plant whose glossy leaves develop dramatic holes as it matures. Give it a moss pole to climb and water when the top few centimetres of soil are dry.', 39.99, 14, 'BRIGHT_INDIRECT', 'MODERATE', FALSE, '/images/plants/fol-monstera.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('TRL-ADANSONII', 'Swiss Cheese Monstera', 'Monstera adansonii, a fast-growing vine with heart-shaped leaves full of oval windows. Lovely trailing from a shelf or trained up a trellis in bright, indirect light.', 24.99, 9, 'BRIGHT_INDIRECT', 'MODERATE', FALSE, '/images/plants/trl-adansonii.svg', (SELECT id FROM category WHERE code = 'TRAILING')),
  ('FOL-SNAKE', 'Snake Plant ''Laurentii''', 'Upright, sword-like leaves edged in gold. One of the toughest houseplants there is: it tolerates low light and irregular watering, and dislikes soggy soil.', 29.99, 22, 'LOW', 'LOW', FALSE, '/images/plants/fol-snake.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('FOL-ZZ', 'ZZ Plant', 'Waxy, deep-green leaflets on arching stems that store water in thick rhizomes. Thrives on neglect in offices and darker rooms; water only when the soil is fully dry.', 34.99, 18, 'LOW', 'LOW', FALSE, '/images/plants/fol-zz.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('TRL-POTHOS', 'Golden Pothos', 'Heart-shaped leaves splashed with gold on long trailing vines. A forgiving beginner plant that grows in most light levels and droops politely when it wants water.', 14.99, 40, 'LOW', 'MODERATE', FALSE, '/images/plants/trl-pothos.svg', (SELECT id FROM category WHERE code = 'TRAILING')),
  ('TRL-PHILO', 'Heartleaf Philodendron', 'Soft, glossy heart-shaped leaves on slender vines that cascade beautifully from hanging pots. Easy-going and quick to grow in medium light, and simple to propagate from cuttings.', 16.99, 25, 'MEDIUM', 'MODERATE', FALSE, '/images/plants/trl-philo.svg', (SELECT id FROM category WHERE code = 'TRAILING')),
  ('FOL-FIDDLE', 'Fiddle Leaf Fig', 'Statement tree with large, violin-shaped leaves. Loves a consistent spot near a bright window and dislikes being moved, cold draughts or overwatering.', 59.99, 6, 'BRIGHT_INDIRECT', 'MODERATE', FALSE, '/images/plants/fol-fiddle.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('FOL-RUBBER', 'Rubber Plant ''Burgundy''', 'Thick, glossy leaves in a deep burgundy that is almost black. Wipe the leaves occasionally to keep them shining and let the soil dry slightly between waterings.', 32.00, 11, 'BRIGHT_INDIRECT', 'MODERATE', FALSE, '/images/plants/fol-rubber.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('FLW-PEACELILY', 'Peace Lily', 'Elegant white blooms above dark green foliage, even in lower light. Keep the soil evenly moist; it wilts dramatically when thirsty and recovers quickly after a drink.', 27.50, 15, 'LOW', 'HIGH', FALSE, '/images/plants/flw-peacelily.svg', (SELECT id FROM category WHERE code = 'FLOWERING')),
  ('FRN-BOSTON', 'Boston Fern', 'Lush, arching fronds that bring a soft, airy feel to any room. Loves humidity and consistently moist soil, so a bright bathroom or kitchen is the ideal home.', 22.99, 12, 'MEDIUM', 'HIGH', TRUE, '/images/plants/frn-boston.svg', (SELECT id FROM category WHERE code = 'FERNS')),
  ('FRN-BIRDNEST', 'Bird''s Nest Fern', 'Glossy, wavy fronds that unfurl from a central rosette like a nest. Enjoys humidity and moist soil, but avoid pouring water directly into the centre of the rosette.', 26.99, 3, 'MEDIUM', 'HIGH', TRUE, '/images/plants/frn-birdnest.svg', (SELECT id FROM category WHERE code = 'FERNS')),
  ('FRN-MAIDENHAIR', 'Maidenhair Fern', 'Delicate, fan-shaped leaflets on fine black stems. A rewarding plant for attentive growers: never let the soil dry out and keep it away from draughts and heaters.', 19.99, 0, 'MEDIUM', 'HIGH', TRUE, '/images/plants/frn-maidenhair.svg', (SELECT id FROM category WHERE code = 'FERNS')),
  ('TRL-SPIDER', 'Spider Plant', 'Arching striped leaves and dangling baby plantlets that are easy to propagate. Adaptable, pet-friendly and a classic choice for hanging baskets and shelves.', 12.99, 50, 'MEDIUM', 'MODERATE', TRUE, '/images/plants/trl-spider.svg', (SELECT id FROM category WHERE code = 'TRAILING')),
  ('PLM-PARLOR', 'Parlor Palm', 'Graceful, feathery fronds on a compact palm that has decorated living rooms since Victorian times. Happy in lower light and safe around cats and dogs.', 29.99, 9, 'LOW', 'MODERATE', TRUE, '/images/plants/plm-parlor.svg', (SELECT id FROM category WHERE code = 'PALMS')),
  ('PLM-ARECA', 'Areca Palm', 'Clusters of golden stems with soft, arching fronds that add a tropical feel. Prefers bright, indirect light and evenly moist but never soggy soil. Mist it in dry winter air.', 49.99, 5, 'BRIGHT_INDIRECT', 'MODERATE', TRUE, '/images/plants/plm-areca.svg', (SELECT id FROM category WHERE code = 'PALMS')),
  ('SUC-PONYTAIL', 'Ponytail Palm', 'Not a true palm but a succulent with a swollen, water-storing trunk and a fountain of curly leaves. Likes plenty of sun and very little water, especially in winter.', 44.99, 7, 'DIRECT', 'LOW', TRUE, '/images/plants/suc-ponytail.svg', (SELECT id FROM category WHERE code = 'SUCCULENTS')),
  ('FOL-CALATHEA', 'Calathea Orbifolia', 'Large, round leaves striped in silver and green. Appreciates humidity, filtered water and evenly moist soil; its leaves curl up when the air or the soil is too dry.', 36.00, 8, 'MEDIUM', 'HIGH', TRUE, '/images/plants/fol-calathea.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('FOL-PRAYER', 'Prayer Plant', 'Patterned leaves with red veins that fold upward at night like hands in prayer. Keep the soil lightly moist and the plant out of harsh direct afternoon sun.', 18.50, 20, 'MEDIUM', 'HIGH', TRUE, '/images/plants/fol-prayer.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('FOL-PILEA', 'Chinese Money Plant', 'Pilea peperomioides, with round, coin-like leaves on slender stems. Rotate it weekly for even growth and share the little pups it produces with friends.', 17.99, 16, 'BRIGHT_INDIRECT', 'MODERATE', TRUE, '/images/plants/fol-pilea.svg', (SELECT id FROM category WHERE code = 'FOLIAGE')),
  ('SUC-ALOE', 'Aloe Vera', 'Fleshy, serrated leaves filled with soothing gel. Needs a sunny windowsill and gritty, fast-draining soil; water deeply but rarely, and less often still in the winter months.', 13.99, 30, 'DIRECT', 'LOW', FALSE, '/images/plants/suc-aloe.svg', (SELECT id FROM category WHERE code = 'SUCCULENTS')),
  ('SUC-JADE', 'Jade Plant', 'Thick, glossy, oval leaves on sturdy branches that slowly grow into a small tree over the years. Loves sun and dry spells between waterings, and is easy to grow from a single leaf.', 21.99, 13, 'DIRECT', 'LOW', FALSE, '/images/plants/suc-jade.svg', (SELECT id FROM category WHERE code = 'SUCCULENTS')),
  ('SUC-ECHEVERIA', 'Echeveria ''Lola''', 'Compact rosette of pastel lavender-grey leaves with a soft, powdery finish. Give it as much sun as possible and let the soil dry out completely before watering again.', 9.99, 35, 'DIRECT', 'LOW', TRUE, '/images/plants/suc-echeveria.svg', (SELECT id FROM category WHERE code = 'SUCCULENTS')),
  ('SUC-XMASCACTUS', 'Christmas Cactus', 'Segmented, arching stems that burst into pink and red flowers in winter. Unlike desert cacti it prefers bright shade and regular watering while it is in bud and flower.', 19.50, 10, 'BRIGHT_INDIRECT', 'MODERATE', TRUE, '/images/plants/suc-xmascactus.svg', (SELECT id FROM category WHERE code = 'SUCCULENTS')),
  ('FLW-ORCHID', 'Phalaenopsis Orchid', 'Moth orchid with long-lasting sprays of white blooms. Water sparingly through the bark mix about once a week and keep it in bright, indirect light, away from cold glass.', 34.99, 4, 'BRIGHT_INDIRECT', 'LOW', TRUE, '/images/plants/flw-orchid.svg', (SELECT id FROM category WHERE code = 'FLOWERING')),
  ('FLW-ANTHURIUM', 'Anthurium ''Red''', 'Glossy, heart-shaped red spathes that last for weeks on end. Enjoys warmth, humidity and soil that dries slightly between waterings. Remove spent flowers to encourage new ones.', 31.99, 9, 'BRIGHT_INDIRECT', 'MODERATE', FALSE, '/images/plants/flw-anthurium.svg', (SELECT id FROM category WHERE code = 'FLOWERING')),
  ('TRL-PEARLS', 'String of Pearls', 'Cascading strands of bead-like leaves that look stunning in a hanging pot. Bright light and infrequent watering keep the little pearls plump and healthy.', 23.99, 2, 'BRIGHT_INDIRECT', 'LOW', FALSE, '/images/plants/trl-pearls.svg', (SELECT id FROM category WHERE code = 'TRAILING')),
  ('TRL-HOYA', 'Hoya Carnosa ''Krimson Queen''', 'Waxy variegated leaves edged in cream and pink, with fragrant star-shaped flower clusters on mature vines. Let it dry out well between drinks and do not cut the old flower spurs.', 27.99, 6, 'BRIGHT_INDIRECT', 'LOW', TRUE, '/images/plants/trl-hoya.svg', (SELECT id FROM category WHERE code = 'TRAILING')),
  ('FLW-BROMELIAD', 'Bromeliad Guzmania', 'A vivid, long-lasting flower bract rising from a rosette of strappy leaves. Keep a little water in the central cup and the potting mix just barely moist.', 25.00, 0, 'MEDIUM', 'LOW', TRUE, '/images/plants/flw-bromeliad.svg', (SELECT id FROM category WHERE code = 'FLOWERING'));
